function refineReservedTriggers(
  data: {
    command_triggers?: DBModmailCommandTriggers;
    custom_commands?: { commands?: DBModmailCustomCommand[] };
    aliases?: { commands?: DBModmailAlias[] };
  },
  ctx: z.RefinementCtx,
): void {
  const reserved = reservedTriggerWords(data.command_triggers);
  const checkBlock = (
    basePath: "custom_commands" | "aliases",
    commands: { trigger: string }[] | undefined,
  ) => {
    commands?.forEach((cmd, index) => {
      const word = cmd.trigger.trim().toLowerCase();
      if (!reserved.has(word)) return;
      ctx.addIssue({
        code: "custom",
        path: [basePath, "commands", index, "trigger"],
        message: `"${cmd.trigger}" ya es un comando de staff (o uno de sus triggers) y nunca se dispararía`,
      });
    });
  };
  checkBlock("custom_commands", data.custom_commands?.commands);
  checkBlock("aliases", data.aliases?.commands);
}
```

