539	/** Por qué el motor NO ejecutó un flujo que sí encajaba con el disparador. */
540	export type DBModerationFlowBlockReason =
541	  | "cooldown" // cooldown por usuario del propio flujo
542	  | "rate_limit" // techo de ejecuciones por minuto del flujo
543	  | "channel_filter" // el canal (o su categoría) no pasa el scope
544	  | "role_filter" // el autor lleva un rol excluido por el scope
545	  | "bot_author" // autor bot y el flujo los ignora
546	  | "admin_author" // autor con permiso de gestión y el flujo los ignora
547	  | "trigger_filter" // los params del disparador no encajan
548	  | "missing_context" // Discord no mandó la pieza que el flujo necesita
549	  | "no_branch"; // ninguna rama pasó y no hay «si no» final
