// ModerationFlowTrigger es el disparador de un flujo de moderación: la clave
// del catálogo `MODERATION_FLOW_TRIGGER_KEYS` más sus params libres. Mismo
// motivo que `AutomationTrigger`: la forma de `Params` la declara el catálogo
// compartido de `@kena/shared/moderation-flows`, no el DB.
type ModerationFlowTrigger struct {
	Type   string         `bson:"type"   json:"type"`
	Params map[string]any `bson:"params" json:"params"`
}

// ModerationFlowScope es el nodo «Scope & filters»: dónde escucha el flujo y a
// quién ignora. `Channels`/`Categories`/`Roles` reusan `ModerationAccessList`
// —el mismo mirror de `DBAccessList` que ya usa `ModerationCommandAccess`—
// porque viven en el mismo vertical; no se comparte entre módulos (mismo
// criterio que documenta `ModerationAccessMode`).
type ModerationFlowScope struct {
	Channels           ModerationAccessList `bson:"channels"               json:"channels"`
	Categories         ModerationAccessList `bson:"categories"             json:"categories"`
	Roles              ModerationAccessList `bson:"roles"                  json:"roles"`
	IgnoreBots         bool                 `bson:"ignore_bots"            json:"ignore_bots"`
	IgnoreAdmins       bool                 `bson:"ignore_admins"          json:"ignore_admins"`
	CooldownSeconds    int                  `bson:"cooldown_seconds"       json:"cooldown_seconds"`
	RateLimitPerMinute int                  `bson:"rate_limit_per_minute"  json:"rate_limit_per_minute"`
}

// ModerationFlowCondition es una condición de una rama (la raíz o una
// alternativa). `Negate` es el interruptor «no». `Params` va SIN TIPAR a
// propósito, igual que `AutomationCondition`: su forma la declara el catálogo
// de `@kena/shared/moderation-flows`.
type ModerationFlowCondition struct {
	ID     string         `bson:"id"     json:"id"`
	Type   string         `bson:"type"   json:"type"`
	Negate bool           `bson:"negate" json:"negate"`
	Params map[string]any `bson:"params" json:"params"`
}

// ModerationFlowStep es un paso: una acción de moderación, `set_variable`,
// `wait` o `stop`. Se reutiliza tanto para `setup` como para los `steps` de
// cada rama.
type ModerationFlowStep struct {
	ID     string         `bson:"id"     json:"id"`
	Type   string         `bson:"type"   json:"type"`
	Params map[string]any `bson:"params" json:"params"`
}

// ModerationFlowBranch es una rama alternativa «else if» / «else»: sin
// condiciones es el «si no» final y debe ir última (lo valida el catálogo
// compartido, no el DB).
type ModerationFlowBranch struct {
	ID            string                    `bson:"id"             json:"id"`
	ConditionMode string                    `bson:"condition_mode" json:"condition_mode"`
	Conditions    []ModerationFlowCondition `bson:"conditions"     json:"conditions"`
	Steps         []ModerationFlowStep      `bson:"steps"          json:"steps"`
}

// ModerationFlow es un flujo de moderación completo: Trigger → Scope &
// filters → Setup → If (condiciones raíz) → then/else. Espejo de
// `DBModerationFlow` (§1 del contrato de flujos), MISMO orden de campos.
//
// `Branches` lleva `omitempty` (bson Y json) a propósito — único campo de
// colección de este struct que lo lleva: "ausente o vacío = sin ramas" es un
// estado legítimo (ver el comentario del campo), igual que `Automation.Branches`
// en `module_automation.go`. El resto de colecciones (`Setup`, `Conditions`,
// `Steps`) NUNCA omitempty: una lista vacía tiene que serializar `[]`.
type ModerationFlow struct {
	// ID es un `crypto.randomUUID()` estable de por vida — va en la URL del
	// editor de la dashboard.
	ID      string                `bson:"id"      json:"id"`
	Name    string                `bson:"name"    json:"name"`
	Enabled bool                  `bson:"enabled" json:"enabled"`
	Trigger ModerationFlowTrigger `bson:"trigger" json:"trigger"`
	Scope   ModerationFlowScope   `bson:"scope"   json:"scope"`
	// Setup son los pasos previos a la bifurcación (típicamente `set_variable`).
	Setup         []ModerationFlowStep `bson:"setup"          json:"setup"`
	ConditionMode string               `bson:"condition_mode" json:"condition_mode"`
	// Conditions son las condiciones de la rama RAÍZ (el «If» del editor).
	// Vacío = siempre pasa.
	Conditions []ModerationFlowCondition `bson:"conditions" json:"conditions"`
	// Steps son los pasos de la rama raíz (el `then`).
	Steps    []ModerationFlowStep   `bson:"steps"    json:"steps"`
	Branches []ModerationFlowBranch `bson:"branches,omitempty" json:"branches,omitempty"`
	// DebugUntil: hasta cuándo se persiste CADA bloqueo como fila propia en
	// `moderation.flow_run_blocks` (ISO-8601). `nil` o pasado = sólo contadores
	// agregados. Es el botón «Debug 15 min» del editor.
	DebugUntil *string `bson:"debug_until" json:"debug_until"`
	CreatedAt  string  `bson:"created_at"  json:"created_at"`
	UpdatedAt  string  `bson:"updated_at"  json:"updated_at"`
}

// ModuleModeration matches `DBModuleModeration`. Field order follows
// `moduleModerationSchema`. Like greeter/tempvoice/giveaway it carries a
// per-module `updated_at` that the repo stamps to `now` on every write.
type ModuleModeration struct {
	SchemaVersion int  `bson:"schema_version"       json:"schema_version"`
	Enabled       bool `bson:"enabled"              json:"enabled"`
	// EnabledSince es la fecha de la PRIMERA activación del módulo en este
	// guild — WRITE-ONCE: se estampa al activar por primera vez y no se
	// reescribe nunca (ni al desactivar ni al reactivar). Sostiene el
	// derecho legacy: un guild que activó moderation antes del corte de
	// `globals.module_premium_cutoffs` conserva el módulo entero gratis.
	// `nil` (campo ausente en Mongo) = nunca activado.
	EnabledSince       *JSONDate                    `bson:"enabled_since,omitempty" json:"enabled_since"`
	CommandMode        ModerationCommandMode        `bson:"command_mode"         json:"command_mode"`
	CommandsGlobal     ModerationCommandAccess      `bson:"commands_global"      json:"commands_global"`
	Commands           map[string]ModerationCommand `bson:"commands"             json:"commands"`
	Mute               ModerationMute               `bson:"mute"                 json:"mute"`
	LogChannelID       *string                      `bson:"log_channel_id"       json:"log_channel_id"`
	TrackNativeActions bool                         `bson:"track_native_actions" json:"track_native_actions"`
	Automod            ModerationAutomod            `bson:"automod"              json:"automod"`
	Protection         ModerationProtection         `bson:"protection"           json:"protection"`
	Escalation         ModerationEscalation         `bson:"escalation"           json:"escalation"`
	Effects            ModerationEffects            `bson:"effects"              json:"effects"`
	Raid               ModerationRaid               `bson:"raid"                 json:"raid"`
	Gate               ModerationGate               `bson:"gate"                 json:"gate"`
	Antinuke           ModerationAntinuke           `bson:"antinuke"             json:"antinuke"`
	Lockdown           ModerationLockdown           `bson:"lockdown"             json:"lockdown"`
	// Flows son los flujos de moderación configurables desde el constructor
	// visual (v4). NUNCA `omitempty`: una lista vacía serializa `[]`, jamás
	// `null` — mismo criterio que `Automations`.
	Flows     []ModerationFlow `bson:"flows"                json:"flows"`
	UpdatedAt JSONDate         `bson:"updated_at"           json:"updated_at"`
}

// ── Defaults ────────────────────────────────────────────────────────────────

// AutomodDefaultTimeoutMs es la duración por defecto del tempmute (5 minutos)
// que se aplica cuando la acción de una regla es `delete_timeout`.
const AutomodDefaultTimeoutMs = 5 * 60 * 1000

// ModerationCommandNames es el catálogo de comandos configurables del módulo,
// en orden de dominio: primero los 12 del v2 (sanciones + historial) y después
// los 11 que llegan con el v3 (canal, voz, casos, raid). El seed del documento
// nuevo y el backfill de un documento viejo recorren esta misma lista, así que
// añadir un comando aquí lo siembra en AMBOS caminos.
var ModerationCommandNames = []string{
	"ban",
	"tempban",
	"unban",
	"kick",
	"mute",
	"tempmute",
	"unmute",
	"avisar",
	"infrs",
	"modinf",
	"delinf",
	"delinfs",
	// v3
	"limpiar",
	"lock",
	"unlock",
	"slowmode",
	"vcmute",
	"vcunmute",
	"vcexpulsar",
	"mover",
	"nota",
	"caso",
	"raid",
}

// ModerationAccessDefault es el acceso SIN restricciones en los tres ejes
// (`all_except []`). A diferencia de tempvoice NO siembra el centinela de canal
// temporal: los comandos de moderación funcionan en cualquier canal por
// defecto, y restringir es opt-in desde la dashboard. Slices frescos en cada
// llamada.
func ModerationAccessDefault() ModerationCommandAccess {
	return ModerationCommandAccess{
		Roles:      ModerationAccessList{Mode: ModerationAccessAllExcept, IDs: []string{}},
		Channels:   ModerationAccessList{Mode: ModerationAccessAllExcept, IDs: []string{}},
		Categories: ModerationAccessList{Mode: ModerationAccessAllExcept, IDs: []string{}},
	}
}

// ModerationCommandDefault es un comando activo, heredando el acceso global,
// con aviso por DM y mensaje VACÍO (el módulo cae en su texto por defecto y la
// dashboard lo enseña como placeholder gris — estilo modmail). `dm_embed.color`
// nace `null`.
func ModerationCommandDefault() ModerationCommand {
	return ModerationCommand{
		Enabled:   true,
		UseGlobal: true,
		Access:    ModerationAccessDefault(),
		Aliases:   []string{},
		DmEnabled: true,
		DmEmbed:   ModerationDmEmbed{Content: "", Color: nil},
	}
}

// DefaultModerationCommands siembra `ModerationCommandNames` con el comando por
// defecto. Map y slices frescos en cada llamada, para que quien mute el
// resultado no contamine otros documentos.
func DefaultModerationCommands() map[string]ModerationCommand {
	out := make(map[string]ModerationCommand, len(ModerationCommandNames))
	for _, name := range ModerationCommandNames {
		out[name] = ModerationCommandDefault()
	}
	return out
}

