20		 *  never appears in the banner (it only validates / widens the payload). */
21		ui?: {
22			/** value of the tab (`useUrlTab`) where the `requires` field renders */
23			tab: string;
24			/** i18n key of the banner text ("X is enabled but Y is missing") */
25			label: string;
26		};
27	}
