29	// Walk a dotted path; returns undefined as soon as any segment is missing or
30	// bottoms out on a non-object.
31	export function getPath(obj: unknown, dotted: string): unknown {
32		let cur: unknown = obj;
33		for (const seg of dotted.split(".")) {
34			if (cur == null || typeof cur !== "object") return undefined;
35			cur = (cur as Record<string, unknown>)[seg];
36		}
37		return cur;
38	}
