40	// First segment of a dotted path — the top-level key the diff is keyed by.
41	export function topKey(dotted: string): string {
42		return dotted.split(".", 1)[0] as string;
43	}
44	
45	/** Unmet deps over the WHOLE form value (not the diff): a rule fires when
46	 *  `is(getPath(value, when))` (default v === true) and
47	 *  `missing(getPath(value, requires))` (default v == null || v === "").
48	 *  Only returns deps with `ui` — the only ones representable in the banner. */
49	export function collectUnmetDependencies<T extends object>(
50		deps: readonly FieldDependency[],
51		value: T,
52	): FieldDependency[] {
53		const unmet: FieldDependency[] = [];
54		for (const dep of deps) {
55			if (!dep.ui) continue;
56			const is = dep.is ?? ((v: unknown) => v === true);
57			if (!is(getPath(value, dep.when))) continue;
58			const missing = dep.missing ?? ((v: unknown) => v == null || v === "");
59			if (missing(getPath(value, dep.requires))) unmet.push(dep);
60		}
61		return unmet;
62	}
63	
64	/** For superRefine of the send-schemas. A rule fires ONLY if topKey(when) is
65	 *  present in `data` (a partial payload). When it fires and topKey(requires) is
66	 *  NOT in data, the required value counts as missing (the server forces clients
67	 *  to send the pair). Rules without a `message` are skipped — they only widen
68	 *  the payload, never validate. */
69	export function dependencyRefiner(
70		deps: readonly FieldDependency[],
71	): (data: Record<string, unknown>, ctx: z.RefinementCtx) => void {
72		return (data, ctx) => {
73			for (const dep of deps) {
74				if (!dep.message) continue;
75				const whenTop = topKey(dep.when);
76				if (!(whenTop in data)) continue;
77				const is = dep.is ?? ((v: unknown) => v === true);
78				if (!is(getPath(data, dep.when))) continue;
79				const requiresTop = topKey(dep.requires);
80				const requiresVal =
81					requiresTop in data ? getPath(data, dep.requires) : undefined;
82				const missing =
83					dep.missing ?? ((v: unknown) => v == null || v === "");
84				if (missing(requiresVal)) {
85					ctx.addIssue({
86						code: "custom",
87						path: dep.requires.split("."),
88						message: dep.message,
89					});
90				}
91			}
92		};
93	}
94	
95	/** Widen the diff: for each dep with topKey(when) ∈ diff and topKey(requires) ∉
96	 *  diff, copy value[topKey(requires)] into the diff. Ignores `is`/`missing`/
97	 *  `message`: payload pairing is unconditional. */
98	export function widenDiffForDependencies<T extends object>(
99		deps: readonly FieldDependency[],
100		diff: Partial<T>,
101		value: T,
102	): void {
103		for (const dep of deps) {
104			const whenTop = topKey(dep.when) as keyof T;
105			const requiresTop = topKey(dep.requires) as keyof T;
106			if (whenTop in diff && !(requiresTop in diff)) {
107				(diff as Record<string, unknown>)[requiresTop as string] = (
108					value as Record<string, unknown>
109				)[requiresTop as string];
110			}
111		}
112	}
113	
114	/** Extracted from the diff loop in usePatchSubmitter, no change in semantics. */
115	export function computeTopLevelDiff<T extends object>(
116		value: T,
117		baseline: T,
118		skipKeys?: readonly (keyof T)[],
119	): Partial<T> {
120		const diff: Partial<T> = {};
121		for (const key of Object.keys(value) as (keyof T)[]) {
122			if (skipKeys?.includes(key)) continue;
123			if (!deepEqual(value[key], baseline[key])) {
124				(diff as Record<string, unknown>)[key as string] = value[key];
125			}
126		}
127		return diff;
128	}
