import type * as z from "zod";
import { deepEqual } from "@/lib/deepEqual";

// Declarative "field X requires field Y" rule. Declared once per module and
// fed to BOTH the send-schema's superRefine (validation) and the diff widener
// (payload pairing) so the two never drift apart.
export interface FieldDependency {
	/** dotted path that triggers the rule, e.g. "captcha.enabled" */
	when: string;
	/** predicate over the value of `when`; default: (v) => v === true */
	is?: (v: unknown) => boolean;
	/** dotted path of the required field, e.g. "captcha.verified_role_id" */
	requires: string;
	/** "is missing" predicate; default: (v) => v == null || v === "" */
	missing?: (v: unknown) => boolean;
	/** i18n key of the issue; if OMITTED, the rule only widens the payload
	 *  (it never validates). */
	message?: string;
	/** Metadata for the generic banner and the tab jump. Without `ui`, the rule
	 *  never appears in the banner (it only validates / widens the payload). */
	ui?: {
		/** value of the tab (`useUrlTab`) where the `requires` field renders */
		tab: string;
		/** i18n key of the banner text ("X is enabled but Y is missing") */
		label: string;
	};
}

// Walk a dotted path; returns undefined as soon as any segment is missing or
// bottoms out on a non-object.
export function getPath(obj: unknown, dotted: string): unknown {
	let cur: unknown = obj;
	for (const seg of dotted.split(".")) {
		if (cur == null || typeof cur !== "object") return undefined;
		cur = (cur as Record<string, unknown>)[seg];
	}
	return cur;
}

// First segment of a dotted path — the top-level key the diff is keyed by.
export function topKey(dotted: string): string {
	return dotted.split(".", 1)[0] as string;
}

/** Unmet deps over the WHOLE form value (not the diff): a rule fires when
 *  `is(getPath(value, when))` (default v === true) and
 *  `missing(getPath(value, requires))` (default v == null || v === "").
 *  Only returns deps with `ui` — the only ones representable in the banner. */
export function collectUnmetDependencies<T extends object>(
	deps: readonly FieldDependency[],
	value: T,
): FieldDependency[] {
	const unmet: FieldDependency[] = [];
	for (const dep of deps) {
		if (!dep.ui) continue;
		const is = dep.is ?? ((v: unknown) => v === true);
		if (!is(getPath(value, dep.when))) continue;
		const missing = dep.missing ?? ((v: unknown) => v == null || v === "");
		if (missing(getPath(value, dep.requires))) unmet.push(dep);
	}
	return unmet;
}

/** For superRefine of the send-schemas. A rule fires ONLY if topKey(when) is
 *  present in `data` (a partial payload). When it fires and topKey(requires) is
 *  NOT in data, the required value counts as missing (the server forces clients
 *  to send the pair). Rules without a `message` are skipped — they only widen
 *  the payload, never validate. */
export function dependencyRefiner(
	deps: readonly FieldDependency[],
): (data: Record<string, unknown>, ctx: z.RefinementCtx) => void {
	return (data, ctx) => {
		for (const dep of deps) {
			if (!dep.message) continue;
			const whenTop = topKey(dep.when);
			if (!(whenTop in data)) continue;
			const is = dep.is ?? ((v: unknown) => v === true);
			if (!is(getPath(data, dep.when))) continue;
			const requiresTop = topKey(dep.requires);
			const requiresVal =
				requiresTop in data ? getPath(data, dep.requires) : undefined;
			const missing =
				dep.missing ?? ((v: unknown) => v == null || v === "");
			if (missing(requiresVal)) {
				ctx.addIssue({
					code: "custom",
					path: dep.requires.split("."),
					message: dep.message,
				});
			}
		}
	};
}

/** Widen the diff: for each dep with topKey(when) ∈ diff and topKey(requires) ∉
 *  diff, copy value[topKey(requires)] into the diff. Ignores `is`/`missing`/
 *  `message`: payload pairing is unconditional. */
export function widenDiffForDependencies<T extends object>(
	deps: readonly FieldDependency[],
	diff: Partial<T>,
	value: T,
): void {
	for (const dep of deps) {
		const whenTop = topKey(dep.when) as keyof T;
		const requiresTop = topKey(dep.requires) as keyof T;
		if (whenTop in diff && !(requiresTop in diff)) {
			(diff as Record<string, unknown>)[requiresTop as string] = (
				value as Record<string, unknown>
			)[requiresTop as string];
		}
	}
}

/** Extracted from the diff loop in usePatchSubmitter, no change in semantics. */
export function computeTopLevelDiff<T extends object>(
	value: T,
	baseline: T,
	skipKeys?: readonly (keyof T)[],
): Partial<T> {
	const diff: Partial<T> = {};
	for (const key of Object.keys(value) as (keyof T)[]) {
		if (skipKeys?.includes(key)) continue;
		if (!deepEqual(value[key], baseline[key])) {
			(diff as Record<string, unknown>)[key as string] = value[key];
		}
	}
	return diff;
}

