package validations

import (
	"kena.bot/api-db-go/internal/domain/dbnotifier"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleNotifierBody es el cuerpo del PATCH del módulo. Sólo `enabled`
// es escribible desde fuera — `schema_version`/`updated_at`/`enabled_since`
// los estampa el repositorio, igual que en el resto de módulos.
type UpdateModuleNotifierBody struct {
	Enabled *bool `json:"enabled,omitempty"`
}

// ParseNotifierSource valida el segmento `:source` de la URL contra las tres
// fuentes soportadas. Un valor desconocido es un 400, no un 404: la ruta
// existe, el parámetro no.
func ParseNotifierSource(raw string) (dbnotifier.Source, *apierrors.CustomError) {
	s := dbnotifier.Source(raw)
	if !s.IsValid() {
		return "", zodItemError("source must be one of youtube|twitch|twitter", "source")
	}
	return s, nil
}

// CreateNotifierSubBody es el cuerpo del POST de una sub nueva. Los campos
// obligatorios difieren por `source` (channel_id / user_id+user_login /
// handle) y esa forma la valida el catálogo de la dashboard, no Go — mismo
// criterio que `UpdateModuleAutomationBody` con la forma de cada
// automatización: duplicar esas reglas aquí sería una tercera copia que se
// desincroniza. Go sólo exige lo mínimo para que el documento sea coherente:
// un canal de Discord donde avisar.
type CreateNotifierSubBody struct {
	DiscordChannelID string `json:"discord_channel_id"`
}

// Validate exige `discord_channel_id` no vacío — sin canal la sub no tiene
// dónde avisar y quedaría configurada a medias.
func (b CreateNotifierSubBody) Validate() *apierrors.CustomError {
	if b.DiscordChannelID == "" {
		return zodItemError("discord_channel_id is required", "discord_channel_id")
	}
	return nil
}

