const (
	moderationCommandModeMsg         = `Invalid option: expected one of "slash"|"prefix"|"both"`
	moderationMuteModeMsg            = `Invalid option: expected one of "auto"|"timeout"|"role"`
	moderationAccessModeMsg          = `Invalid option: expected one of "only"|"all_except"`
	automodActionMsg                 = `Invalid option: expected one of "delete"|"delete_warn"|"delete_timeout"|"delete_kick"|"delete_ban"`
	moderationEscalationActionMsg    = `Invalid option: expected one of "mute"|"tempmute"|"kick"|"tempban"|"ban"`
	moderationCountableTypeMsg       = `Invalid option: expected one of "warn"|"note"|"mute"|"tempmute"|"kick"|"ban"|"tempban"`
	moderationEffectPolicyMsg        = `Invalid option: expected one of "always"|"never"|"ask"`
	moderationRaidActionMsg          = `Invalid option: expected one of "alert"|"lockdown"|"kick"|"ban"`
	moderationGateActionMsg          = `Invalid option: expected one of "alert"|"kick"|"ban"|"mute"`
	moderationNukePunishmentMsg      = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"`
	moderationNukePunishOrInheritMsg = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"|"inherit"`
)

// moderationEnum checks an already-decoded enum value against its set. Unlike
// the raw-JSON `parseEnumRequired` used by other verticals, these values
// arrive pre-typed (the struct decode already happened) — this is the ONLY
// remaining gate, and it catches "" exactly like every other out-of-set value.
func moderationEnum(value string, set map[string]bool, msg, property string) *apierrors.CustomError {
	if set[value] {
		return nil
	}
	return zodItemError(msg, property)
}

func validateModerationAccessList(l *dbguild.ModerationAccessList, prefix string) *apierrors.CustomError {
	if l == nil {
		return nil
	}
	return moderationEnum(string(l.Mode), moderationAccessModeSet, moderationAccessModeMsg, prefix+"mode")
}

func validateModerationCommandAccess(a *dbguild.ModerationCommandAccess, prefix string) *apierrors.CustomError {
	if a == nil {
		return nil
	}
	if err := validateModerationAccessList(&a.Roles, prefix+"roles."); err != nil {
		return err
	}
	if err := validateModerationAccessList(&a.Channels, prefix+"channels."); err != nil {
		return err
	}
	return validateModerationAccessList(&a.Categories, prefix+"categories.")
}

func validateModerationAutomod(a *dbguild.ModerationAutomod) *apierrors.CustomError {
	if a == nil {
		return nil
	}
	for _, rule := range []struct {
		action   dbguild.AutomodAction
		property string
	}{
		{a.Mentions.Action, "automod.mentions.action"},
		{a.Words.Action, "automod.words.action"},
		{a.Invites.Action, "automod.invites.action"},
		{a.Spam.Action, "automod.spam.action"},
		{a.Duplicates.Action, "automod.duplicates.action"},
		{a.Caps.Action, "automod.caps.action"},
		{a.Links.Action, "automod.links.action"},
		{a.Emojis.Action, "automod.emojis.action"},
		{a.Attachments.Action, "automod.attachments.action"},
	} {
		if err := moderationEnum(string(rule.action), automodActionSet, automodActionMsg, rule.property); err != nil {
			return err
		}
	}
	return nil
}

func validateModerationEscalation(e *dbguild.ModerationEscalation) *apierrors.CustomError {
	if e == nil {
		return nil
	}
	for i, t := range e.CountTypes {
		property := "escalation.count_types." + strconv.Itoa(i)
		if err := moderationEnum(string(t), moderationCountableTypeSet, moderationCountableTypeMsg, property); err != nil {
			return err
		}
	}
	for i, rule := range e.Rules {
		property := "escalation.rules." + strconv.Itoa(i) + ".action"
		if err := moderationEnum(string(rule.Action), moderationEscalationActionSet, moderationEscalationActionMsg, property); err != nil {
			return err
		}
	}
	return nil
}

func validateModerationEffects(e *dbguild.ModerationEffects) *apierrors.CustomError {
	if e == nil {
		return nil
	}
	for _, f := range []struct {
		policy   dbguild.ModerationEffectPolicy
		property string
	}{
		{e.VoiceDisconnectOnMute.Policy, "effects.voice_disconnect_on_mute.policy"},
		{e.ServerMuteOnMute.Policy, "effects.server_mute_on_mute.policy"},
		{e.StripRolesOnMute.Policy, "effects.strip_roles_on_mute.policy"},
		{e.PurgeOnBan.Policy, "effects.purge_on_ban.policy"},
		{e.PurgeOnKick.Policy, "effects.purge_on_kick.policy"},
	} {
		if err := moderationEnum(string(f.policy), moderationEffectPolicySet, moderationEffectPolicyMsg, f.property); err != nil {
			return err
		}
	}
	return nil
}

func validateModerationAntinuke(a *dbguild.ModerationAntinuke) *apierrors.CustomError {
	if a == nil {
		return nil
	}
	if err := moderationEnum(string(a.Punishment), moderationNukePunishmentSet, moderationNukePunishmentMsg, "antinuke.punishment"); err != nil {
		return err
	}
	keys := make([]string, 0, len(a.Limits))
	for k := range a.Limits {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		property := "antinuke.limits." + k + ".punishment"
		if err := moderationEnum(string(a.Limits[k].Punishment), moderationNukePunishmentOrInheritSet, moderationNukePunishOrInheritMsg, property); err != nil {
			return err
		}
	}
	return nil
}

// ValidateUpdateModuleModeration closes the two gaps `updateModuleModerationSchema`
// covers on the Node/dashboard side but the Go strict decode does not:
//
//  1. Every enum-typed leaf (`command_mode`, the three access `mode`s,
//     `automod.*.action`, `escalation.rules[].action`/`count_types[]`,
//     `effects.*.policy`, `mute.mode`, `raid.action`, `gate.action`,
//     `antinuke.punishment`/`limits[].punishment`) is a bare `type X string`
//     alias — Go's decoder accepts ANY string, `""` included, and an empty
//     value sits in the document looking configured while doing nothing.
//  2. The ONE cross-field rule the dashboard enforces (`moderationDependencies`
//     in moderation-schema.ts): with `mute.mode === "role"` but no
//     `mute.role_id`, long/indefinite mutes are IMPOSSIBLE — not degraded,
//     impossible — because the bot has no role to apply. It only lives in the
//     browser's zod (`superRefine`/`dependencyRefiner`), so a direct PATCH
//     bypassed it entirely.
//
// Every other v3 block degrades on its own by design (raid/gate/antinuke
// alerts fall back to the mod-log channel when unset, an empty channel list
// means "all", an escalation with no rungs just never fires) and is
// deliberately NOT blocked here — blocking those would be the same false
// guard that was removed from tempvoice.
//
// A nil pointer means "not touched by this PATCH" throughout, matching the
// rest of the struct's presence-based merge semantics.
func ValidateUpdateModuleModeration(body *UpdateModuleModerationBody) *apierrors.CustomError {
	if body == nil {
		return nil
	}

	if body.CommandMode != nil {
		if err := moderationEnum(string(*body.CommandMode), moderationCommandModeSet, moderationCommandModeMsg, "command_mode"); err != nil {
			return err
		}
	}

	if err := validateModerationCommandAccess(body.CommandsGlobal, "commands_global."); err != nil {
		return err
	}

	if body.Commands != nil {
		names := make([]string, 0, len(*body.Commands))
		for name := range *body.Commands {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			cmd := (*body.Commands)[name]
			if err := validateModerationCommandAccess(&cmd.Access, "commands."+name+".access."); err != nil {
				return err
			}
		}
	}

	if body.Mute != nil {
		if err := moderationEnum(string(body.Mute.Mode), moderationMuteModeSet, moderationMuteModeMsg, "mute.mode"); err != nil {
			return err
		}
		if body.Mute.Mode == dbguild.ModerationMuteModeRole &&
			(body.Mute.RoleID == nil || *body.Mute.RoleID == "") {
			return zodItemError("Required", "mute.role_id")
		}
	}

	if err := validateModerationAutomod(body.Automod); err != nil {
		return err
	}
	if err := validateModerationEscalation(body.Escalation); err != nil {
		return err
	}
	if err := validateModerationEffects(body.Effects); err != nil {
		return err
	}

	if body.Raid != nil {
		if err := moderationEnum(string(body.Raid.Action), moderationRaidActionSet, moderationRaidActionMsg, "raid.action"); err != nil {
			return err
		}
	}
	if body.Gate != nil {
		if err := moderationEnum(string(body.Gate.Action), moderationGateActionSet, moderationGateActionMsg, "gate.action"); err != nil {
			return err
		}
	}
	if err := validateModerationAntinuke(body.Antinuke); err != nil {
		return err
	}

	return nil
}

